// Output variable for the color
layout(location = 0) out vec4 fragColor[TD_NUM_COLOR_BUFFERS];
void main()
{
	// This allows things such as order independent transparency
	// and Dual-Paraboloid rendering to work properly
	TDCheckDiscard();

	vec4 outcol = vec4(0.0, 0.0, 0.0, 0.0);

	vec3 normal = normalize(vVert.worldSpaceNorm);
	vec2 texCoord0 = vVert.texCoord0.st;
	vec4 colorMapColor = color;
	if (constantColor < 0.1){
		colorMapColor = texture(sColorMap, texCoord0.st);
	}
	vec3 viewVec = normalize(uTDMats[vVert.cameraIndex].camInverse[3].xyz - vVert.worldSpacePos.xyz );

	vec4 uvMap = vec4(-1.0,-1.0,0.0,0.0);
	uvMap = vec4(texCoord0.st,0.0,1.0);

	// Flip the normals on backfaces
	if (!gl_FrontFacing) {
		normal = -normal;
	}


	float alpha = vVert.color.a * colorMapColor.a;
	alpha = texture(sLookup,vec2(alpha,0.5)).r;
	if (softedge == 0 && invertMask < 1.0){
		alpha = colorMapColor.a;
	}
	outcol = colorMapColor;


	// Dithering, does nothing if dithering is disabled
	outcol = TDDither(outcol);

	// Modern GL removed the implicit alpha test, so we need to apply
	// it manually here. This function does nothing if alpha test is disabled.
	TDAlphaTest(alpha);

	outcol.a = alpha;
	fragColor[0] = TDOutputSwizzle(outcol);


	// TD_NUM_COLOR_BUFFERS will be set to the number of color buffers
	// active in the render. By default we want to output zero to every
	// buffer except the first one.
	for (int i = 1; i < TD_NUM_COLOR_BUFFERS; i++)
	{
		uvMap.a = alpha;
		uvMap.b = shapeID;
		fragColor[i] = uvMap;
	}
}

