	# writes a matrix into the pretransform matrix parameter of a given Geo COMP
	def writeMatrix(self, path=None, matrix=None):
		mat = []
		for i in range(4):
			for j in range(4):
				mat.append(matrix[j,i])
		op(path).par.xformmatrixop.expr = 'tdu.Matrix({0})'.format(mat)

	# returns the pivot of the selected area
	def Getpivot(self):
		return self.ownerComp.op('tools/shapeTransform/pivots').center


	# calculate roation angle for selected shape(s)
	def getRotation(self, shape=None, multi=False, offset=[0,0]):
		sDict = self.ownerComp.ext.Selector.getSelected()

		tx = offset[0]
		ty = offset[1]

		if multi:
			pivotPos = tdu.Position([sDict['rotate'][0][1]*1.0,sDict['rotate'][0][2]*1.0,0])
		else:
			pivotPos = shape.ext.Transform.shapePivot

		keyPos = [sDict['rotate'][0][3]*1.0,sDict['rotate'][0][4]*1.0]
		org = math.atan2(pivotPos[1]-keyPos[1],pivotPos[0]-keyPos[0])
		offset = math.atan2(pivotPos[1]-(keyPos[1]+ty),pivotPos[0]-(keyPos[0]+tx))
		r = math.degrees(offset-org)
		rotation = {'r':r, 'pivot':pivotPos}
		return rotation

	# calculate scale amount for selected shape(s)
	def getScale(self, shape=None, multi=False, offset=[0,0]):
		sDict = self.ownerComp.ext.Selector.getSelected()

		keyPos = [sDict['scale'][0][3]*1.0,sDict['scale'][0][4]*1.0]
		tx = offset[0]
		ty = offset[1]

		if multi:
			pivotPos = tdu.Position([sDict['scale'][0][1]*1.0,sDict['scale'][0][2]*1.0,0])
			transform = self.ownerComp.op('tools/shapeTransform').localTransform
		else:
			pivotPos = shape.ext.Transform.shapePivot
			transform = shape.localTransform

		# get a rotation matrix going
		s, r, t = transform.decompose()
		rotMat = tdu.Matrix()
		rotMat.rotate(0,0,-r[2])

		org = tdu.Vector(pivotPos[0]-keyPos[0],pivotPos[1]-keyPos[1],0.0)
		offset = tdu.Vector(pivotPos[0]-(keyPos[0]+tx),pivotPos[1]-(keyPos[1]+ty),0.0)
		org *= rotMat
		offset *= rotMat

		if sDict['scale'][0][0] == 1 or sDict['scale'][0][0] == 5:
			scale = tdu.Vector(1.0,offset[1]/org[1],0)
		elif sDict['scale'][0][0] == 3 or sDict['scale'][0][0] == 7:
			scale = tdu.Vector(offset[0]/org[0],1.0,0)
		else:
			scale = tdu.Vector(offset[0]/org[0],offset[1]/org[1],0)

		scale = {'sx':scale[0],'sy':scale[1],'pivot':pivotPos}
		return scale

