vec3 solveQuadratic(float A, float B, float C){
	vec3 roots = vec3(0.0);
	if (A == 0.0){
		if (B != 0.0){
			roots.x = -C / B;
			roots.z = 1.0;
			return roots;
		}
		if (C != 0.0){
			return roots;
		}
		roots.z = 1.0;
		return roots;
	}

	float det2, det;

	det2 = B*B - 4*A*C;
	if (det2 < 0){
		return roots;
	}
	det = sqrt(det2);
	roots.x = (-B + det) / (2*A);

	if (det == 0.0){
		roots.z = 1;
		return roots;
	}
	roots.y = (-B - det) / (2*A);
	roots.z = 2;
	return roots;
}

vec2 uvCoords(in vec4 xPos, in vec4 yPos, in vec2 p)
{
	vec2 uv = vec2(-1,-1);
	float Ax, Bx, Cx, Dx, Ay, By, Cy, Dy, A, B, C;

	//These are all uniforms for a given quad. Calculate on CPU.
	if (abs(xPos.x - xPos.y) < 0.0001){
		xPos.x += 0.0001; 
	}
	if (abs(xPos.z - xPos.w) < 0.0001){
		xPos.z += 0.0001; 
	}
	if (abs(xPos.x - xPos.w) < 0.0001){
		xPos.x += 0.0001; 
	}
	if (abs(xPos.z - xPos.y) < 0.0001){
		xPos.z += 0.0001; 
	}
	if (abs(yPos.x - yPos.y) < 0.0001){
		yPos.x += 0.0001; 
	}
	if (abs(yPos.z - yPos.w) < 0.0001){
		yPos.z += 0.0001; 
	}
	if (abs(yPos.x - yPos.w) < 0.0001){
		yPos.x += 0.0001; 
	}
	if (abs(yPos.z - yPos.y) < 0.0001){
		yPos.z += 0.0001; 
	}
	Ax = (xPos.w - xPos.x) - (xPos.z - xPos.y);
	Bx = (xPos.x - xPos.y); //problem if 0!
	Cx = (xPos.z - xPos.y);
	Dx = xPos.y;

	Ay = (yPos.w - yPos.x) - (yPos.z - yPos.y);
	By = (yPos.x - yPos.y);
	Cy = (yPos.z - yPos.y);
	Dy = yPos.y;

	float ByCx_plus_AyDx_minus_BxCy_minus_AxDy = (By * Cx) + (Ay * Dx) - (Bx * Cy) - (Ax * Dy);
	float ByDx_minus_BxDy = (By * Dx) - (Bx * Dy);

	A = (Ay*Cx)-(Ax*Cy);

	//These must be calculated per-vertex, and passed through as interpolated values to the pixel-shader 
	B = (Ax * p.y) + ByCx_plus_AyDx_minus_BxCy_minus_AxDy - (Ay * p.x);
	C = (Bx * p.y) + ByDx_minus_BxDy - (By * p.x);

	/*	vec3 roots = solveQuadratic(A,B,C);

	float denom, thisRoot;
	for (int i; i<int(roots.z); ++i){
		if (i == 0){
			thisRoot = roots.x;
		}
		else {
			thisRoot = roots.y;
		}
		denom = (Ax-Bx) * (1.0 - thisRoot) + (Cx - Dx) * thisRoot;

		if (denom == 0.0){
			continue;
		}
		uv.t = thisRoot;
		uv.s = ((Ax-p.x) + uv.t*(Cx-Ax))/denom;

		if (uv.s < 0.0 || uv.s > 1.0 || uv.t < 0.0 || uv.t > 1.0){
			continue;
		}
	}*/

	//These must be calculated per-pixel using the interpolated B, C and x from the vertex shader along with some of the other uniforms.
	if ((B*B-(4.0f*A*C)) < 0.0){
		uv.s = -1.0;
	}
	else{
		if (sqrt((B*B-(4.0*A*C))) == 0.0){
			uv.s = ((-B) + sqrt((B*B-(4.0*A*C))))/(A*2.0);
		}
		else{
			uv.s = ((-B) - sqrt((B*B-(4.0*A*C))))/(A*2.0);
		}

	}
	uv.t = (p.x - (uv.s * Cx) - Dx)/((uv.s*Ax)+Bx);

	return uv;
}

layout(location = 0) out vec4 fragColor[TD_NUM_COLOR_BUFFERS];
void main()
{
    mat3 currMat = mat3(0.0);
	vec2 texCoord0 = vVert.texCoord0.st;
	vec2 texCoord1 = vVert.texCoord1.st;
	vec2 texCoord2 = vVert.texCoord2.st;

	vec4 colorMapColor = color;

	if (constantColor < 0.5){
		colorMapColor = texture(colorMap, texCoord2.st);
	}

	vec4 uvMap = vec4(-1.0,-1.0,0.0,0.0);
	uvMap = vec4(texCoord2.st,0.0,1.0);

	float alpha = 1.0;
	float alphaS = 1.0;
	float alphaT = 1.0;
	if (softEdge > 0.0 && softedgeType == 0.0){ 
		if (texCoord1.s < softEdge){
			alphaS = map(texCoord1.s,0.0,softEdge,0.0,1.0);
		}else if (texCoord1.s > 1.0 - softEdge){
			alphaS = map(texCoord1.s,1.0-softEdge,1.0,1.0,0.0);
		}
		if (texCoord1.t < softEdge){
			alphaT = map(texCoord1.t,0.0,softEdge,0.0,1.0);
		}else if (texCoord1.t > 1.0 - softEdge){
			alphaT = map(texCoord1.t,1.0-softEdge,1.0,1.0,0.0);
		}
		alpha = min(alphaS,alphaT)*colorMapColor.a;;
		alpha = texture(sLookup,vec2(alpha,0.5)).r;
	}
	else if(softEdge > 0.0 && softedgeType == 1.0){

		currMat = getMatrix();
		vec3 homPos = vec3(0.0);
		// calculate remap to rectangle homography
		homPos = inverse(currMat) * vec3(texCoord1.st, 1.0);
		homPos.xy  = homPos.xy / homPos.z;
		if (homPos.r < 0.0 || homPos.r > 1.0 || homPos.g < 0.0 || homPos.g > 1.0){

			vec2 p1 = vec2(0.0,0.0);
			vec2 p2 = vec2(1.0,0.0);
			vec2 p3 = vec2(0.0,1.0);
			vec2 p4 = vec2(1.0,1.0);
			vec3 ph1 = currMat * vec3(p1,1.0);
			ph1.xy = ph1.xy / ph1.z;
			vec3 ph2 = currMat * vec3(p2,1.0);
			ph2.xy = ph2.xy / ph2.z;
			vec3 ph3 = currMat * vec3(p3,1.0);
			ph3.xy = ph3.xy / ph3.z;
			vec3 ph4 = currMat * vec3(p4,1.0);
			ph4.xy = ph4.xy / ph4.z;

			vec2 uv1, uv2, uv3, uv4;

			uv1 = vec2(1.0) - uvCoords(vec4(ph1.x,ph2.x,p2.x,p1.x),vec4(ph1.y,ph2.y,p2.y,p1.y),texCoord1.st);
			uv2 = vec2(1.0) - uvCoords(vec4(ph2.x,ph4.x,p4.x,p2.x),vec4(ph2.y,ph4.y,p4.y,p2.y),texCoord1.st);
			uv3 = vec2(1.0) - uvCoords(vec4(ph4.x,ph3.x,p3.x,p4.x),vec4(ph4.y,ph3.y,p3.y,p4.y),texCoord1.st);
			uv4 = vec2(1.0) - uvCoords(vec4(ph3.x,ph1.x,p1.x,p3.x),vec4(ph3.y,ph1.y,p1.y,p3.y),texCoord1.st);

			if (uv1.x > 1.0 || uv1.x < 0.0 || uv1.y > 1.0 || uv1.y < 0.0){
				uv1 = vec2(0.0);
			}
			if (uv2.x > 1.0 || uv2.x < 0.0 || uv2.y > 1.0 || uv2.y < 0.0){
				uv2 = vec2(0.0);
			}
			if (uv3.x > 1.0 || uv3.x < 0.0 || uv3.y > 1.0 || uv3.y < 0.0){
				uv3 = vec2(0.0);
			}
			if (uv4.x > 1.0 || uv4.x < 0.0 || uv4.y > 1.0 || uv4.y < 0.0){
				uv4 = vec2(0.0);
			}

			alpha = texture(sLookup,uv1+uv2+uv3+uv4).r;
			alpha = colorMapColor.a * alpha;
		}
	}
	else{
		alpha = colorMapColor.a;
	}
    fragColor[0] = vec4(colorMapColor.rgb,alpha);

    for (int i = 1; i < TD_NUM_COLOR_BUFFERS; i++)
	{
		uvMap.a = alpha;
		uvMap.b = shapeID;
		fragColor[i] = uvMap;
	}
}

