"""
Extension classes enhance TouchDesigner component networks with python
functionality. An extension can be accessed via ext.ExtensionClassName from
any operator within the extended component. If the extension is "promoted", all
its attributes with capitalized names can be accessed directly through the
extended component, e.g. op('yourComp').ExtensionMethod()
"""
class Parameter:

	def __init__(self, ownerComp):
		# The component to which this extension is attached
		self.ownerComp = ownerComp

	def Setpar(self, name=None, value=None):
		if name and value != None:
			if self.ownerComp.op('parameters').pars(name):
				if name == 'Uvmatrix':
					self.ownerComp.op('parameters').pars(name)[0].expr = value
				else:
					self.ownerComp.op('parameters').pars(name)[0].val = value

	def GetDefinition(self):
		defDict = {}
		parDict = {}
		shapeDict = {}
		for i in self.ownerComp.op('parameters').customPars:
			if i.name == 'Uvmatrix':
				parDict[i.name] = i.expr
			else:
				parDict[i.name] = i.val
		defDict['parameters'] = parDict
		shapeDict['pointOffset'] = self.ownerComp.op('pointOffset').text
		shapeDict['keyOffset'] = self.ownerComp.op('keyOffset').text
		shapeDict['uvOffset'] = self.ownerComp.op('uvOffset').text
		shapeDict['uvOffsetTexture'] = self.ownerComp.op('uvOffsetTexture').text
		shapeDict['softedgePoints'] = self.ownerComp.op('softedgePoints').text
		shapeDict['homography'] = self.ownerComp.op('homography').text
		shapeDict['softedgeHomography'] = self.ownerComp.op('softedgeHomography').text
		defDict['shapeDef'] = shapeDict
		defDict['shapeXform'] = self.ownerComp.par.xformmatrixop.expr
		defDict['type'] = '1'
		defDict['path'] = self.ownerComp.path
		defDict['layer'] = self.ownerComp.par.drawpriority.eval()
		return defDict

	def SetDefinition(self, defDict={}, undo=True):
		oldDef = self.GetDefinition()
		parameters = defDict.get('parameters',None)
		if parameters:
			for i in parameters:
				self.Setpar(name=i, value=parameters[i])

		shapeDict = defDict.get('shapeDef', None)
		if shapeDict:
			self.ownerComp.op('pointOffset').text = shapeDict['pointOffset']
			self.ownerComp.op('keyOffset').text = shapeDict['keyOffset']
			self.ownerComp.op('uvOffset').text = shapeDict['uvOffset']
			self.ownerComp.op('uvOffsetTexture').text = shapeDict['uvOffsetTexture']
			self.ownerComp.op('softedgePoints').text = shapeDict['softedgePoints']
			self.ownerComp.op('homography').text = shapeDict['homography']
			self.ownerComp.op('softedgeHomography').text = shapeDict['softedgeHomography']

		shapeXform = defDict.get('shapeXform', None)
		if shapeXform:
			self.ownerComp.par.xformmatrixop.expr = shapeXform

		newDef = self.GetDefinition()
		defDict = {}
		defDict['action'] = 'parChange'
		defDict['before'] = [oldDef]
		defDict['after'] = [newDef]
		if undo == 'end':
			parent.KanProj.SaveUndo(defDict=defDict, end=True)
		elif undo:
			parent.KanProj.SaveUndo(defDict=defDict)
		return newDef

