vec3 solveQuadratic(float A, float B, float C){
	vec3 roots = vec3(0.0);
	if (A == 0.0){
		if (B != 0.0){
			roots.x = -C / B;
			roots.z = 1.0;
			return roots;
		}
		if (C != 0.0){
			return roots;
		}
		roots.z = 1.0;
		return roots;
	}

	float det2, det;

	det2 = B*B - 4*A*C;
	if (det2 < 0){
		return roots;
	}
	det = sqrt(det2);
	roots.x = (-B + det) / (2*A);

	if (det == 0.0){
		roots.z = 1;
		return roots;
	}
	roots.y = (-B - det) / (2*A);
	roots.z = 2;
	return roots;
}

