"""
Extension classes enhance TouchDesigner component networks with python
functionality. An extension can be accessed via ext.ExtensionClassName from
any operator within the extended component. If the extension is "promoted", all
its attributes with capitalized names can be accessed directly through the
extended component, e.g. op('yourComp').ExtensionMethod()
"""

class Interface:
	"""
	Interface description
	"""
	def __init__(self, ownerComp):
		# The component to which this extension is attached
		self.ownerComp = ownerComp


	def Read(self, shapeDict=None, undo=True):
		parent.Ui.ext.Uistate.setUi = True
		if shapeDict:
			if shapeDict.get('multiple', False) == False:
				shape = shapeDict['shapes'][0]
				if shape:
					if shape.get('matrix',False):
						if op('selected')['layer'][0] > 0:
							op('layer').SetPara(matrix=shape.get('matrix',False))
						else:
							op('multi').SetPara(matrix=shape.get('matrix',False))
					else:
						shapeType = shape['type']
						# if selected is a layer
						if shapeType == '0':
							op('layer').SetPara(shapeDef=shape)
						# if selected is a rectangle
						if shapeType == '1':
							op('rect').SetPara(shapeDef=shape)
						# if selected is a freeform
						if shapeType == '2':
							op('free').SetPara(shapeDef=shape)
			else:
				shape = shapeDict['shapes'][0]
				op('multi').SetPara(shapeDef=shape)
		else:
			debug('set ui to nothing selected')
		delScript = 'op("{0}").ext.Uistate.setUi = False'.format(parent.Ui)
		run(delScript,delayFrames=2)


	def Set(self, source=None, defDict=None, undo=True):
		if not parent.Ui.ext.Uistate.setUi:
			project = parent.mottoKantan.op('project')
			sDict = project.ext.Selector.getSelected()

			if source == 'layer':
				currSelectPar = sDict['layer']
				currSelect = sDict['shape']
			else:
				currSelectPar = sDict['shape']
				currSelect = currSelectPar

			pars = project.ext.Selector.getShape(itemId=currSelectPar)

			# if it's a parameter, set the parameter
			parameters = defDict.get('parameters',None)
			if parameters:
				# the pivot is special and needs to be set seperatly
				pivotX = parameters.get('Custompivotx',None)
				pivotY = parameters.get('Custompivoty',None)
				if (pivotX != None or pivotY != None):
					pivotPos = {'pivotX':pivotX,'pivotY':pivotY}
					project.SetPivot(pos=pivotPos)
				if undo == True:
					undo = parent.Ui.ext.Uistate.setUi==False
				for i in pars:
					a = i.SetDefinition(defDict=defDict, undo=undo)
					self.Read(shapeDict={'shapes':[a]})
					parent.Ui.op('textureEdit/gadgets').Read(shapeDict={'shapes':[a]})
			# reseting certain shape aspects
			reset = defDict.get('reset',None)
			if reset:
				keystone = reset.get('keystone',None)
				warp = reset.get('warp',None)
				if keystone:
					project.RectReset(itemId=currSelectPar, keystone=True)
				elif warp:
					project.RectReset(itemId=currSelectPar, warp=True)

			if currSelect:
				shapes = project.ext.Selector.getShape(itemId=currSelect)
			else:
				shapes = []

			transform = defDict.get('transform',None)
			if transform:
				scale = transform.get('scale',None)
				rotate = transform.get('rotate',None)
				translate = transform.get('translate',None)
				delta = transform.get('delta',False)
				multi = min(len(shapes)-1,1)
				shift = 1
				if parent.Ui.ext.Uistate.shiftKey:
					shift = 10
					if rotate:
						rotate['z'] *= shift
					if translate:
						translate['x'] *= shift
						translate['y'] *= shift

				if multi:
					if scale:
						project.ResetMulti()
						project.MultiTrans(scale=scale, delta=True)
						project.ResetMulti(start=False, update=True)
					if rotate:
						project.ResetMulti()
						project.MultiTrans(rotate=rotate, delta=True)
						project.ResetMulti(start=False, update=True)
					if translate:
						project.ResetMulti()
						project.MultiTrans(translate=translate, delta=True)
						project.ResetMulti(start=False, update=True)

				for i in shapes:
					if scale:
						shapeDict = i.Scale(scale=scale, delta=delta, multi=multi)
						self.Read(shapeDict={'shapes':[shapeDict]})
					if rotate:
						shapeDict = i.Rotate(rotate=rotate, delta=delta, multi=multi)
					if translate:
						shapeDict = i.Translate(translate=translate, delta=delta)

	def StateRead(self, mainState=None, shapeState=None):
		if mainState:
			mainTools = op('toolBtns')
			if mainState == 'createRect':
				if mainTools.op('rect').panel.state == 0:
					mainTools.op('rect').click(1)
			elif mainState == 'createFree':
				if mainTools.op('free').panel.state == 0:
					mainTools.op('free').click(1)
			elif mainState == 'transform':
				if mainTools.op('select').panel.state == 0:
					mainTools.op('select').click(1)
			elif mainState == 'shapeManipulate':
				if mainTools.op('direct').panel.state == 0:
					mainTools.op('direct').click(1)

		if shapeState:
			shapeTools = op('extraTools')
			if shapeState == 'rectangleWarp':
				if shapeTools.op('rectWarp').panel.state == 0:
					shapeTools.op('rectWarp').click(1)
			elif shapeState == 'rectangleAddRow':
				if shapeTools.op('rectAddRow').panel.state == 0:
					shapeTools.op('rectAddRow').click(1)
			elif shapeState == 'rectangleAddCol':
				if shapeTools.op('rectAddCol').panel.state == 0:
					shapeTools.op('rectAddCol').click(1)
			elif shapeState == 'transKey':
				if shapeTools.op('rectKey').panel.state == 0:
					shapeTools.op('rectKey').click(1)
				if shapeTools.op('freeKey').panel.state == 0:
					shapeTools.op('freeKey').click(1)
			elif shapeState == 'freeformInsertKey':
				if shapeTools.op('freeAddKey').panel.state == 0:
					shapeTools.op('freeAddKey').click(1)	
			elif shapeState == 'freeformConvert':
				if shapeTools.op('convertKey').panel.state == 0:
					shapeTools.op('convertKey').click(1)
			elif shapeState == 'freeformSoftedge':
				if shapeTools.op('softedgeKey').panel.state == 0:
					shapeTools.op('softedgeKey').click(1)
		return

	def StateSet(self, mainState=None, shapeState=None):
		if mainState:
			if mainState == 'select':
				parent.mottoKantan.op('project').ext.Selector.State(newState='xform')
			elif mainState == 'direct':
				parent.mottoKantan.op('project').ext.Selector.State(newState='tool',shapeTool='transKey')
			elif mainState == 'rect':
