# panelValue - the PanelValue object that changed
# 
# Make sure the corresponding toggle is enabled in the Panel Execute DAT.

def valueChange(panelValue):
	owner = panelValue.owner
	row = int(panelValue%owner.par.tablerows)
	cols = owner.par.tablecols
	column = int(panelValue/owner.par.tablerows)

	realId = owner.op('alldata')[row+1,'realId'].val
	if panelValue.name == 'celloverid':
		if panelValue > -1:
			parent.mottoKantan.op('project').RollOff(rollType=['shapeDisplay'])
			parent.mottoKantan.op('project').RollOn(rollType=['shapeDisplay'], shapeId=realId, rollId=realId)
		else:
			parent.mottoKantan.op('project').RollOff(rollType=['shapeDisplay'])

	if panelValue.name == 'cellselectid':

		if panelValue > -1:
			if column == cols-1:
				parent.mottoKantan.op('project').ShowShape(itemId=realId)
			elif column == cols-2:
				parent.mottoKantan.op('project').LockShape(itemId=realId)
			else:
				if owner.op('alldata')[row+1,'type'].val == 'layer':
					a = parent.mottoKantan.op('project').SelectLayer(itemId=realId, add=False)
				else:
					a = parent.mottoKantan.op('project').SelectShape(itemId=realId, add=False)
				parent.Ui.op('main/gadgets').Read(shapeDict=a)
	return

"""
Extension classes enhance TouchDesigner component networks with python
functionality. An extension can be accessed via ext.ExtensionClassName from
any operator within the extended component. If the extension is "promoted", all
its attributes with capitalized names can be accessed directly through the
extended component, e.g. op('yourComp').ExtensionMethod()
"""

class Treebrowser:
	"""
	Treebrowser description
	"""
	def __init__(self, ownerComp):
		# The component to which this extension is attached
		self.ownerComp = ownerComp

	def Select(self, panelValue=None):
		if panelValue != None:
			owner = panelValue.owner
			row = panelValue%owner.par.tablerows
			realId = owner.op('alldata')[row+1,'id'].val.split('.')[-1]

			if panelValue.name == 'celloverid':
				if panelValue > -1:
					parent.mottoKantan.op('project').RollOff(rollType=['shapeDisplay'])
					parent.mottoKantan.op('project').RollOn(rollType=['shapeDisplay'], shapeId=realId, rollId=realId)
				else:
					parent.mottoKantan.op('project').RollOff(rollType=['shapeDisplay'])

			if panelValue.name == 'cellselectid':
				if panelValue > -1:
					if owner.op('alldata')[row+1,'type'].val == 'layer':
						a = parent.mottoKantan.op('project').SelectLayer(itemId=realId, add=False)
					else:
						a = parent.mottoKantan.op('project').SelectShape(itemId=realId, add=False)
					parent.Ui.op('main/gadgets').Read(shapeDict=a)

