"""
Extension classes enhance TouchDesigner component networks with python
functionality. An extension can be accessed via ext.ExtensionClassName from
any operator within the extended component. If the extension is "promoted", all
its attributes with capitalized names can be accessed directly through the
extended component, e.g. op('yourComp').ExtensionMethod()
"""

class Renderpick:
	"""
	Renderpick description
	"""
	def __init__(self, ownerComp):
		# The component to which this extension is attached
		self.ownerComp = ownerComp
		self.pickedObj = set([])
		self.rollObj = None
		self.eventType = ['header','inside','lselect','mselect','rselect','drop']
		self.pickedPath = {'inside':None,'lselect':None}
		self.renderPickOp = None
		self.select = False

	def Event(self, renderPickDat, events, eventsPrev):
		#self.renderPick = renderPickDat
		projectOP = parent.mottoKantan.op('project')
		uiState = projectOP.ext.Selector.getState()
		startDAT = op('startUV')

		if renderPickDat.name == 'renderpickCanvas':
			panelSource = parent.Ui.op('main/canvas')
		else:
			panelSource = parent.mottoKantan.op('project/onScreen')

		for event, eventPrev in zip(events, eventsPrev):

			thisEvent = self.eventType[event.row]

			# creating shapes, selecting and moving widgets
			if thisEvent == 'lselect':
				self.renderPickOp = renderPickDat
				# ctrl key lets you add
				add = False
				if panelSource.panel.ctrl:
					add = True

				# add widget to select list and start movement
				if event.selectStart:
					if event.pickOp == None:
						projectOP.ClearSelects()
						projectOP.SetSelectType()
						if projectOP.ext.Selector.getState()[1] in ['rectAddRow','rectAddCol']:
							projectOP.State(newState='tool',shapeTool='rectangleWarp')
					else:
						self.select = True
						self.pickedPath['lselect'] = event.pickOp
						# save out u, v
						startDAT.clear()
						startDAT.appendRow([event.u,event.v])

						# we are creating a rectangle
						if uiState[0] == 'cRect':
							uv = self.uvToPixel(u=event.u, v=event.v)
							projectOP.ext.Layerizer.AddRect(pnt1=uv, start=True)

						# we are creating or changing a freeform shape
						elif uiState[0] == 'cFree':
							# close a shape
							if 'createKeyWidget' in event.pickOp.tags and event.instanceId == 0:
								a = projectOP.ext.Layerizer.AddFree(end=True)
								parent.Ui.op('main/gadgets').Read(shapeDict={'shapes':[a]})
								parent.Ui.op('textureEdit/gadgets').Read(shapeDict={'shapes':[a]})
							# add another point to the shape
							else:
								uv = self.uvToPixel(u=event.u, v=event.v)
								projectOP.ext.Layerizer.AddFree(pnt1=uv, start=True)

						# insert a key to the free shape
						elif uiState[1] == 'freeInsertKey':
							if 'outline' in event.pickOp.tags:
								uv = self.uvToPixel(u=event.u, v=event.v)
								point = math.floor(event.texture.x)
								key = math.floor(point/3)*3
								# calculate the relative position inbetween keys
								startPos = event.pickOp.points[key].Cd[0]
								endPos = event.pickOp.points[key+3].Cd[0]

								relPos = tdu.remap(event.color[0],startPos,endPos,0,1)

								projectOP.ext.Transformer.FreeInsertKey(tx=uv[0], ty=uv[1], key=key, dt=relPos)
						# convert key
						elif uiState[1] == 'freeConvertKey':
							if 'freeKeyWidget' in event.pickOp.tags:
								projectOP.SelectFreeKey(itemId=event.instanceId, add=add)
								projectOP.ext.Transformer.FreeConvertKey()

						# translating shapes, keys or handles
						else:
							if event.pickOp:
								if 'shapeDisplay' in event.pickOp.tags:
									shapeId = event.pickOp.parent().digits
									sShapes = projectOP.ext.Selector.getSelected()
									if shapeId in sShapes['shape']:
										if uiState == ['shapetool', 'rectAddRow']:
											a = projectOP.AddRow(itemId=shapeId, vPos=event.texture.y)
										elif uiState == ['shapetool', 'rectAddCol']:
											a = projectOP.AddCol(itemId=shapeId, uPos=event.texture.x)
										else:
											a = projectOP.SelectShape(itemId=shapeId, add=add)

									else:
										a = projectOP.SelectShape(itemId=shapeId, add=add)

									parent.Ui.op('main/gadgets').Read(shapeDict=a)
									parent.Ui.op('textureEdit/gadgets').Read(shapeDict=a)

								if 'keyWidget' in event.pickOp.tags:
									projectOP.SelectRectKey(itemId=event.instanceId, add=add)
									projectOP.ext.Transformer.TranslateKey()

								if 'rectEdgeWidget' in event.pickOp.tags:
									projectOP.SelectRectEdgeKey(itemId=event.instanceId, add=add)
									projectOP.ext.Transformer.RectEdgeTranslateKey()
									#projectOP.ext.Transformer.TranslateKey()

								elif 'warpKeyWidget' in event.pickOp.tags:
									projectOP.SelectRectWarpKey(itemId=event.instanceId, add=add)
									projectOP.ext.Transformer.RectWarpKey()

								elif 'warpHandleWidget' in event.pickOp.tags:
									projectOP.SelectRectWarpHandle(itemId=event.instanceId)
									projectOP.ext.Transformer.RectWarpHandle()

								elif 'shapeScaleWidget' in event.pickOp.tags:
									projectOP.SelectShapeScaleKey(itemId=event.texture.y)
									projectOP.ext.Transformer.ShapeTransformKey(start=True, scale=True, copy=parent.Ui.ext.Uistate.altKey)

								elif 'shapeDragWidget' in event.pickOp.tags:
									projectOP.ext.Transformer.ShapeTransformKey(start=True, translate=True, copy=parent.Ui.ext.Uistate.altKey)

								elif 'shapeRotateWidget' in event.pickOp.tags:
									projectOP.SelectShapeRotateKey(itemId=event.texture.y)
									projectOP.ext.Transformer.ShapeTransformKey(start=True, rotate=True, copy=parent.Ui.ext.Uistate.altKey)

								elif 'freeKeyWidget' in event.pickOp.tags:
									projectOP.SelectFreeKey(itemId=event.instanceId, add=add)
									projectOP.ext.Transformer.TranslateKey()

								elif 'freeHandleWidget' in event.pickOp.tags:
									projectOP.SelectFreeHandle(itemId=event.instanceId)
									projectOP.ext.Transformer.FreeTranslateHandle(start=True)

								elif 'edgeKeyWidget' in event.pickOp.tags:
									projectOP.SelectEdgeKey(itemId=event.instanceId, add=add)
									projectOP.ext.Transformer.TranslateEdgeKey()

								elif 'edgeHandleWidget' in event.pickOp.tags:
									projectOP.SelectEdgeHandle(itemId=event.instanceId)
									projectOP.ext.Transformer.FreeTranslateEdgeHandle(start=True)

								elif 'rowColWidget' in event.pickOp.tags:
									projectOP.SelectRowCol(itemId=event.color[0], add=add)


				# call translate function on selected items
				elif event.select:

					# we are creating a rectangle
					if uiState[0] == 'cRect':
						uv = self.uvToPixel(u=event.u, v=event.v)
						projectOP.ext.Layerizer.AddRect(pnt2=uv, drag=True)

					# we are changing a freeform handle
					elif uiState[0] == 'cFree':
						uv = self.uvToPixel(u=event.u, v=event.v)
						projectOP.ext.Layerizer.AddFree(handle=uv, drag=True)

					# we are changing the insterted key handle
					elif uiState[1] == 'freeInsertKey':
						uv = self.uvToPixel(u=event.u-startDAT[0,0], v=event.v-startDAT[0,1], delta=True)
						deltaU = uv[0]
						deltaV = uv[1]
						projectOP.ext.Transformer.FreeTranslateHandle(tx=deltaU, ty=deltaV, lock=True)

					# convert key
					elif uiState[1] == 'freeConvertKey':
						selected = self.pickedPath['lselect']
						if selected:
							if 'freeKeyWidget' in selected.tags:
								thisU = event.u-startDAT[0,0]
								thisV = event.v-startDAT[0,1]
								uv = self.uvToPixel(u=thisU, v=thisV, delta=True)
								deltaU = uv[0]
								deltaV = uv[1]
								projectOP.ext.Transformer.FreeTranslateHandle(tx=deltaU, ty=deltaV, lock=True)

					# translating shapes, keys or handles
					else:
						selected = self.pickedPath['lselect']
						if selected:
							thisU = event.u-startDAT[0,0]
							thisV = event.v-startDAT[0,1]
							uv = self.uvToPixel(u=thisU, v=thisV, delta=True)
							deltaU = uv[0]
							deltaV = uv[1]
							if 'keyWidget' in selected.tags:
								projectOP.ext.Transformer.TranslateKey(tx=deltaU, ty=deltaV)
							elif 'rectEdgeWidget' in selected.tags:
								projectOP.ext.Transformer.RectEdgeTranslateKey(stop=False, tx=deltaU, ty=deltaV)
							elif 'warpKeyWidget' in selected.tags:
								projectOP.ext.Transformer.RectWarpKey(tx=deltaU, ty=deltaV)
							elif 'warpHandleWidget' in selected.tags:
								projectOP.ext.Transformer.RectWarpHandle(tx=deltaU, ty=deltaV)
							elif 'shapeScaleWidget' in selected.tags:
								shapeDict = projectOP.ext.Transformer.ShapeTransformKey(tx=deltaU, ty=deltaV, scale=True)
								parent.Ui.op('main/gadgets').Read(shapeDict={'shapes':[shapeDict]})
							elif 'shapeDragWidget' in selected.tags:
								projectOP.ext.Transformer.ShapeTransformKey(tx=deltaU, ty=deltaV, translate=True)
							elif 'shapeRotateWidget' in selected.tags:
								projectOP.ext.Transformer.ShapeTransformKey(tx=deltaU, ty=deltaV, rotate=True)
							elif 'freeKeyWidget' in selected.tags:
								projectOP.ext.Transformer.TranslateKey(tx=deltaU, ty=deltaV)
							elif 'freeHandleWidget' in selected.tags:
								projectOP.ext.Transformer.FreeTranslateHandle(tx=deltaU, ty=deltaV, lock=True)
							elif 'edgeKeyWidget' in selected.tags:
								projectOP.ext.Transformer.TranslateEdgeKey(tx=deltaU, ty=deltaV)
							elif 'edgeHandleWidget' in selected.tags:
								projectOP.ext.Transformer.FreeTranslateEdgeHandle(tx=deltaU, ty=deltaV, lock=True)

				# stop translate on selected items
				elif event.selectEnd:
					self.select = False

					# finish creating a rectangle
					if uiState[0] == 'cRect':
						uv = self.uvToPixel(u=event.u, v=event.v)
						pnt1 = self.uvToPixel(u=startDAT[0,0], v=startDAT[0,1])
						a = projectOP.ext.Layerizer.AddRect(pnt1=pnt1, pnt2=uv, end=True)
						parent.Ui.op('main/gadgets').Read(shapeDict={'shapes':[a]})
						parent.Ui.op('textureEdit/gadgets').Read(shapeDict={'shapes':[a]})

					# finish inserting a key
					elif uiState[1] == 'freeInsertKey':
						projectOP.ext.Transformer.FreeTranslateHandle(stop=True)

					# convert key
					elif uiState[1] == 'freeConvertKey':
						projectOP.ext.Transformer.FreeTranslateHandle(stop=True)

					# finish translating shapes, keys or handles
					else:
						selected = self.pickedPath['lselect']
						if selected:
							if 'keyWidget' in selected.tags:
								projectOP.ext.Transformer.TranslateKey(stop=True)
							elif 'rectEdgeWidget' in selected.tags:
								#projectOP.ext.Transformer.TranslateKey(stop=True)
								projectOP.ext.Transformer.RectEdgeTranslateKey(stop=True)
							elif 'warpKeyWidget' in selected.tags:
								projectOP.ext.Transformer.RectWarpKey(stop=True)
							elif 'warpHandleWidget' in selected.tags:
								projectOP.ext.Transformer.RectWarpHandle(stop=True)
							elif 'shapeScaleWidget' in selected.tags or 'shapeDragWidget' in selected.tags or 'shapeRotateWidget' in selected.tags:
								projectOP.ext.Transformer.ShapeTransformKey(stop=True)
							elif 'freeKeyWidget' in selected.tags:
								projectOP.ext.Transformer.TranslateKey(stop=True)
							elif 'freeHandleWidget' in selected.tags:
								projectOP.ext.Transformer.FreeTranslateHandle(stop=True)
							elif 'edgeKeyWidget' in selected.tags:
								projectOP.ext.Transformer.TranslateEdgeKey(stop=True)
							elif 'edgeHandleWidget' in selected.tags:
								projectOP.ext.Transformer.FreeTranslateEdgeHandle(stop=True)

					self.pickedPath['lselect'] = None


			elif thisEvent == 'inside':
				if not self.select:
					#this is all about rollovers
					if event.pickOp != None and eventPrev.pickOp == None:
						self.insideAdd(event, eventPrev, panelSource)
					elif event.pickOp != None and eventPrev.pickOp != None:
						self.insideAdd(event, eventPrev, panelSource)
					#elif event.pickOp == None and eventPrev.pickOp != None:
					#	projectOP.RollOff(rollType=eventPrev.pickOp.tags)
					elif event.pickOp == None and eventPrev.pickOp != None:
						self.insideClear(event, eventPrev, panelSource)
						if eventPrev.pickOp:
							projectOP.RollOff(rollType=eventPrev.pickOp.tags)

			#elif thisEvent == 'drop':
			#	debug('dragging across. drop:', event.pickOp)

		return

	def insideAdd(self, event, eventsPrev, panelSource):
		shapeId = None
		rollId = None
		# what am I rolling over
		if 'keyWidget' in event.pickOp.tags:
			shapeId = event.texture.x
			rollId = event.instanceId
		elif 'rectEdgeWidget' in event.pickOp.tags:
			shapeId = event.texture.x
			rollId = event.instanceId
		elif 'shapeScaleWidget' in event.pickOp.tags:
			rollId = event.texture.y
		elif 'shapeRotateWidget' in event.pickOp.tags:
			rollId = event.texture.y
		elif 'warpKeyWidget' in event.pickOp.tags:
			rollId = event.instanceId
		elif 'warpHandleWidget' in event.pickOp.tags:
			shapeId = event.texture.x
			rollId = event.instanceId
		elif 'shapeDisplay' in event.pickOp.tags:
			rollId = event.pickOp.parent().digits
			shapeId = event.pickOp.parent().digits
		elif 'freeKeyWidget' in event.pickOp.tags:
			rollId = event.instanceId
		elif 'freeHandleWidget' in event.pickOp.tags:
			rollId = event.instanceId
		elif 'edgeKeyWidget' in event.pickOp.tags:
			rollId = event.instanceId
		elif 'edgeHandleWidget' in event.pickOp.tags:
			rollId = event.instanceId
		elif 'rowColWidget' in event.pickOp.tags:
			rollId = event.color[0]

		if event.pickOp != eventsPrev.pickOp:
			if eventsPrev.pickOp:
				parent.mottoKantan.op('project').RollOff(rollType=eventsPrev.pickOp.tags)
			parent.mottoKantan.op('project').RollOn(rollType=event.pickOp.tags, shapeId=shapeId, rollId=rollId)
		elif 'outline' in event.pickOp.tags:
			parent.mottoKantan.op('project').SetInsertPointPos(tx=event.pos[0],ty=event.pos[1])

		return

	# this adds a widget to the select list
	def insideClear(self, event, eventsPrev, panelSource):
		return

	# convert uv to pixels
	def uvToPixel(self, u=0, v=0, delta=False):

		if self.renderPickOp:
			renderOp = self.renderPickOp.par.rendertop.eval()
			camera = renderOp.par.camera.eval()

			w = renderOp.width
			h = renderOp.height
			camTransform = camera.localTransform
			s, r, t = camTransform.decompose()
			camS = s[0]
			camTx = t[0]
			camTy = t[1]
			camOrtho = camera.par.orthowidth
			ratio = camOrtho / w

			if not delta:
				u = (u*2-1)/2
				v = (v*2-1)/2
				u = u * camOrtho * camS + t[0]
				v = v * h * ratio * camS + t[1]
			else:
				u = u * camOrtho * camS
				v = v * h * ratio * camS

		return [int(u),int(v)]

